SourceCode.Declaration:
[CustomAPI('Calculate item open balance ', 'Calculates open amount in sales line for item' , 'Test information')]
[AIPluginOperationAttribute]
[DataContract]
internal final class AVAItemOpenSalesAmount               implements ICustomAPI
{

    private ItemId  itemId;
    private CurrencyCode CurrencyCode;
    private AmountCur openAmount; 



}

Method.Source:
[CustomAPIRequestParameter('The item number', true),
DataMember('itemId')]
public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}

[CustomAPIResponseProperty('The current item open amount'),
    DataMember('balance')]
    public AmountCur parmOpenAmount(AmountCur _openAmount = openAmount)
{
    openAmount = _openAmount;
    return openAmount;
}

[CustomAPIResponseProperty('The currency code for the item  balance'),
    DataMember('currencyCode')]
    public CurrencyCode parmCurrencyCode(CurrencyCode _currencyCode = currencyCode)
{
    currencyCode = _currencyCode;
    return currencyCode;
}

public void run(Args _args)
{
    SalesLine salesLine;    
    changecompany('usmf') //Can add company as input to allow switching
    {
        select firstonly salesLine
                order by salesLine.LineAmount desc
            where salesLine.ItemId == this.parmItemId() ;

        this.parmOpenAmount(salesLine.LineAmount);
    }
}
